ALTER TABLE public.profiles ADD COLUMN job_title text, ADD COLUMN is_active boolean NOT NULL DEFAULT true;
REVOKE UPDATE ON public.profiles FROM authenticated;
GRANT UPDATE (full_name, email) ON public.profiles TO authenticated;
ALTER TABLE public.transactions ADD COLUMN author_name text;
UPDATE public.transactions t SET author_name = COALESCE(p.full_name, p.email, 'Colaborador') FROM public.profiles p WHERE p.id = t.user_id;
CREATE OR REPLACE FUNCTION public.is_active_member(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id = _user_id AND is_active); $$;
CREATE OR REPLACE FUNCTION public.set_transaction_author() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF TG_OP = 'INSERT' THEN IF auth.uid() IS NOT NULL THEN NEW.user_id := auth.uid(); END IF; SELECT COALESCE(full_name, email, 'Colaborador') INTO NEW.author_name FROM public.profiles WHERE id = NEW.user_id; ELSE NEW.user_id := OLD.user_id; NEW.author_name := OLD.author_name; END IF; RETURN NEW; END; $$;
CREATE TRIGGER transaction_author BEFORE INSERT OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.set_transaction_author();
DROP POLICY "Users can delete own transactions" ON public.transactions;
DROP POLICY "Admins delete all transactions" ON public.transactions;
REVOKE DELETE ON public.transactions FROM authenticated;
CREATE POLICY "Active members only" ON public.transactions AS RESTRICTIVE FOR ALL TO authenticated USING (public.is_active_member(auth.uid())) WITH CHECK (public.is_active_member(auth.uid()));
CREATE TABLE public.deletion_attempts (user_id uuid PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 0);
GRANT ALL ON public.deletion_attempts TO service_role;
ALTER TABLE public.deletion_attempts ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.consume_deletion_attempt(_user_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE n integer; BEGIN INSERT INTO public.deletion_attempts AS d (user_id, attempts) VALUES (_user_id, 1) ON CONFLICT (user_id) DO UPDATE SET attempts = CASE WHEN d.window_start < now() - interval '1 minute' THEN 1 ELSE d.attempts + 1 END, window_start = CASE WHEN d.window_start < now() - interval '1 minute' THEN now() ELSE d.window_start END RETURNING attempts INTO n; RETURN n <= 5; END; $$;
REVOKE ALL ON FUNCTION public.consume_deletion_attempt(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.consume_deletion_attempt(uuid) TO service_role;
GRANT ALL ON public.profiles, public.transactions, public.user_roles TO service_role;